"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { LayoutDashboard, Users, CreditCard, ScrollText, LogOut, Settings, BookOpen, ChevronDown, MessageSquare } from "lucide-react";
import { cn } from "@/lib/utils";
import { logout } from "@/app/[locale]/login/actions";
import { useState, useEffect } from "react";

const sidebarItems = [
    {
        title: "Dashboard",
        href: "/admin",
        icon: LayoutDashboard,
    },
    {
        title: "Usuarios",
        href: "/admin/users",
        icon: Users,
    },
    {
        title: "Transacciones",
        href: "/admin/transactions",
        icon: CreditCard,
    },
    {
        title: "Lecturas",
        href: "/admin/readings",
        icon: ScrollText,
    },
    {
        title: "Documentación",
        href: "/admin/docs",
        icon: BookOpen,
        subItems: [
            { title: "Visión & Filosofía", href: "/admin/docs/vision" },
            { title: "Arquitectura", href: "/admin/docs/architecture" },
            { title: "Contenido Base", href: "/admin/docs/content" },
            { title: "Negocio", href: "/admin/docs/business" },
            { title: "Planificación", href: "/admin/docs/ideas" },
        ]
    },
    {
        title: "Prompts IA",
        href: "/admin/prompts",
        icon: MessageSquare,
    },
    {
        title: "Ajustes",
        href: "/admin/settings",
        icon: Settings,
    },
];

export function AdminSidebar() {
    const pathname = usePathname();
    const [docsOpen, setDocsOpen] = useState(pathname.startsWith("/admin/docs"));

    // Mantener abierto si estamos en una subruta de docs
    useEffect(() => {
        if (pathname.startsWith("/admin/docs")) {
            setDocsOpen(true);
        }
    }, [pathname]);

    return (
        <div className="flex h-full w-64 flex-col bg-slate-900 border-r border-slate-800">
            <div className="flex h-16 items-center px-6 border-b border-slate-800">
                <span className="text-lg font-bold text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-indigo-400 uppercase tracking-wider">
                    SOS Admin
                </span>
            </div>
            <div className="flex-1 overflow-y-auto py-4">
                <nav className="space-y-1 px-3">
                    {sidebarItems.map((item) => {
                        const isActive = pathname === item.href;
                        const isDocs = item.title === "Documentación";
                        const hasSubItems = !!item.subItems;

                        return (
                            <div key={item.title} className="space-y-1">
                                <div className="flex items-center group">
                                    <Link
                                        href={item.href}
                                        className={cn(
                                            "flex flex-1 items-center gap-3 rounded-lg px-3 py-2 text-sm font-medium transition-colors",
                                            pathname === item.href || (isDocs && pathname.startsWith(item.href))
                                                ? "bg-purple-900/20 text-purple-400"
                                                : "text-slate-400 hover:bg-slate-800/50 hover:text-slate-200"
                                        )}
                                    >
                                        <item.icon className="h-5 w-5" />
                                        {item.title}
                                    </Link>

                                    {hasSubItems && (
                                        <button
                                            onClick={(e) => {
                                                e.preventDefault();
                                                setDocsOpen(!docsOpen);
                                            }}
                                            className="px-2 py-2 text-slate-500 hover:text-white transition-colors"
                                        >
                                            <ChevronDown className={cn("h-4 w-4 transition-transform duration-200", docsOpen && "rotate-180")} />
                                        </button>
                                    )}
                                </div>

                                {isDocs && docsOpen && item.subItems && (
                                    <div className="ml-9 space-y-1">
                                        {item.subItems.map((sub) => {
                                            const subActive = pathname === sub.href;
                                            return (
                                                <Link
                                                    key={sub.href}
                                                    href={sub.href}
                                                    className={cn(
                                                        "block rounded-lg px-3 py-1.5 text-xs font-medium transition-colors",
                                                        subActive
                                                            ? "text-purple-400"
                                                            : "text-slate-500 hover:text-slate-300"
                                                    )}
                                                >
                                                    {sub.title}
                                                </Link>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </nav>
            </div>
            <div className="border-t border-slate-800 p-4">
                <button
                    onClick={() => logout()}
                    className="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:bg-red-900/10 hover:text-red-400"
                >
                    <LogOut className="h-5 w-5" />
                    Cerrar Sesión
                </button>
            </div>
        </div>
    );
}

"use client";

import { motion } from "framer-motion";
import { Sparkles, Star, Shield, Target, Quote, Disc, Compass } from "lucide-react";
import GlowingBorderCard from "@/components/landing/GlowingBorderCard";
import { useTranslations } from "next-intl";

interface AstroInterpretationProps {
    data: {
        summary: string;
        core_personality: string;
        strengths: string[];
        challenges: string[];
        evolutionary_advice: string;
    };
    locale?: string;
}

export default function AstroInterpretation({ data, locale = 'es' }: AstroInterpretationProps) {
    const t = useTranslations('AstrologyPage.interpretation');

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="space-y-8"
        >
            <div className="text-center mb-8">
                <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-xs font-bold uppercase tracking-widest mb-4">
                    <Sparkles className="w-3 h-3" />
                    {t('ai_soul_interpretation')}
                </div>
                <h2 className="text-3xl font-serif text-white">{t('title')}</h2>
            </div>

            {/* Summary Card */}
            <GlowingBorderCard glowColor="purple" className="relative group overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                    <Quote className="w-24 h-24 text-white" />
                </div>
                <div className="p-8 relative z-10">
                    <h3 className="text-indigo-400 font-bold uppercase tracking-widest text-xs mb-3 flex items-center gap-2">
                        <Star className="w-4 h-4" />
                        {t('summary_title')}
                    </h3>
                    <p className="text-xl font-serif text-slate-100 leading-relaxed italic">
                        "{data.summary}"
                    </p>
                </div>
            </GlowingBorderCard>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Core Personality */}
                <div className="glass p-6 rounded-3xl border border-white/5 bg-slate-900/40">
                    <h3 className="text-white font-bold mb-4 flex items-center gap-2">
                        <Target className="w-5 h-5 text-indigo-500" />
                        {t('core_title')}
                    </h3>
                    <p className="text-slate-300 leading-relaxed text-sm">
                        {data.core_personality}
                    </p>
                </div>

                {/* Soul Advice */}
                <div className="glass p-6 rounded-3xl border border-white/5 bg-indigo-950/20">
                    <h3 className="text-white font-bold mb-4 flex items-center gap-2">
                        <Sparkles className="w-5 h-5 text-indigo-400" />
                        {t('advice_title')}
                    </h3>
                    <p className="text-slate-300 leading-relaxed text-sm">
                        {data.evolutionary_advice}
                    </p>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Strengths */}
                <div className="space-y-4">
                    <h3 className="text-emerald-400 font-bold uppercase tracking-widest text-xs px-2 flex items-center gap-2">
                        <Shield className="w-4 h-4" />
                        {t('strengths_title')}
                    </h3>
                    {data.strengths.map((strength, i) => (
                        <motion.div
                            key={i}
                            initial={{ opacity: 0, x: -10 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: 0.1 * i }}
                            className="p-4 rounded-2xl bg-emerald-500/5 border border-emerald-500/10 text-emerald-100 text-sm"
                        >
                            {strength}
                        </motion.div>
                    ))}
                </div>

                {/* Challenges */}
                <div className="space-y-4">
                    <h3 className="text-orange-400 font-bold uppercase tracking-widest text-xs px-2 flex items-center gap-2">
                        <Sparkles className="w-4 h-4" />
                        {t('challenges_title')}
                    </h3>
                    {data.challenges.map((challenge, i) => (
                        <motion.div
                            key={i}
                            initial={{ opacity: 0, x: 10 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: 0.1 * i }}
                            className="p-4 rounded-2xl bg-orange-500/5 border border-orange-500/10 text-orange-100 text-sm"
                        >
                            {challenge}
                        </motion.div>
                    ))}
                </div>
            </div>
        </motion.div>
    );
}

"use client";

import { useState, useEffect } from "react";
import AnimatedSection from "@/components/landing/AnimatedSection";
import { ArrowLeft, Star, Disc, MapPin, Calendar, Compass, Sparkles, Wand2, Loader2 } from "lucide-react";
import { Link } from "@/i18n/routing";
import { Button } from "@/components/ui/button";
import GlowingBorderCard from "@/components/landing/GlowingBorderCard";
import { WesternChartData } from "@/lib/astrology-api";
import AstrologyWheel from "@/components/astrology/AstrologyWheel";
import PlanetIcon from "@/components/astrology/PlanetIcon";
import ZodiacIcon from "@/components/astrology/ZodiacIcon";
import AstroInterpretation from "@/components/astrology/AstroInterpretation";
import { supabase } from "@/lib/supabase/client";
import { toast } from "sonner";
import { useTranslations } from "next-intl";
import InsufficientAuraModal from "@/components/dashboard/InsufficientAuraModal";
import AuraActionButton from "@/components/ui/AuraActionButton";
import DailyHoroscopeCard from "@/components/astrology/DailyHoroscopeCard";

interface AstrologyClientProps {
    profile: any;
    initialChartData: WesternChartData | null;
    initialInterpretation: any | null;
    t: any;
    tz: any;
    locale: string;
}

export default function AstrologyClient({
    profile,
    initialChartData,
    initialInterpretation,
    t,
    tz,
    locale
}: AstrologyClientProps) {
    const [interpretation, setInterpretation] = useState(initialInterpretation);
    const [isLoading, setIsLoading] = useState(false);
    const [balance, setBalance] = useState<number | null>(null);
    const [auraCost, setAuraCost] = useState<number>(20); // Default fallback
    const [insufficientAuraModalOpen, setInsufficientAuraModalOpen] = useState(false);
    const t_interp = useTranslations('AstrologyPage.interpretation');

    // Sync state with props when server data changes (e.g. after profile update)
    useEffect(() => {
        setInterpretation(initialInterpretation);
    }, [initialInterpretation]);

    useEffect(() => {
        const fetchInitialData = async () => {
            try {
                // Fetch balance via API (more reliable than direct RPC from browser)
                const creditsRes = await fetch('/api/credits');
                if (creditsRes.ok) {
                    const creditsData = await creditsRes.json();
                    setBalance(creditsData.balance ?? 0);
                }

                // Fetch dynamic cost for astrology analysis
                const { data: { user } } = await supabase.auth.getUser();
                if (user) {
                    const { data: readingTypes } = await supabase
                        .from('reading_types')
                        .select('credit_cost')
                        .eq('code', 'astrology_full')
                        .single();

                    if (readingTypes) {
                        setAuraCost(readingTypes.credit_cost);
                    }
                }
            } catch (err) {
                console.error('Error fetching initial data:', err);
            }
        };
        fetchInitialData();
    }, []);

    const handleInterpret = async () => {
        if (!initialChartData) return;

        setIsLoading(true);
        try {
            const res = await fetch('/api/astrology/interpret', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ chartData: initialChartData, locale })
            });

            const data = await res.json();

            if (!res.ok) {
                if (res.status === 402) {
                    setInsufficientAuraModalOpen(true);
                } else {
                    toast.error(data.error || "Error");
                }
                return;
            }

            setInterpretation(data);
            setBalance(data.newBalance);
            toast.success(t_interp('interpretation_generated'));

            // Scroll to interpretation
            setTimeout(() => {
                document.getElementById('astro-interpretation')?.scrollIntoView({ behavior: 'smooth' });
            }, 100);

        } catch (error) {
            console.error(error);
            toast.error(t_interp('error_oracle'));
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <main className="max-w-5xl mx-auto p-6 relative z-10">
            {/* Header */}
            <AnimatedSection>
                <div className="flex flex-col md:flex-row items-center justify-between gap-6 mb-10">
                    <div className="flex items-center gap-4">
                        <Link href="/dashboard">
                            <Button variant="ghost" className="text-slate-400 hover:text-white p-2 h-12 w-12 rounded-2xl glass">
                                <ArrowLeft className="w-6 h-6" />
                            </Button>
                        </Link>
                        <div>
                            <h2 className="text-xs font-bold text-indigo-400 uppercase tracking-[0.3em] mb-1">{t.title_natal}</h2>
                            <h1 className="text-3xl font-serif text-white">{t.chart_title.replace('{name}', profile?.full_name || "Ti")}</h1>
                            <p className="text-slate-400 text-sm flex items-center gap-2 mt-1">
                                <MapPin className="w-3 h-3" />
                                {profile?.birth_place || t.location_unknown}
                                <span className="opacity-30">|</span>
                                <Calendar className="w-3 h-3" />
                                {profile?.birth_date} {profile?.birth_time ? profile.birth_time.split(':').slice(0, 2).join(':') : ""}
                            </p>
                        </div>
                    </div>

                    {!initialChartData ? (
                        <Link href="/dashboard">
                            <Button className="bg-indigo-600 hover:bg-indigo-700 text-white">
                                {t.setup_button}
                            </Button>
                        </Link>
                    ) : (
                        <div className="flex flex-col items-end gap-2">
                            <div className="flex gap-4">
                                <div className="text-center px-4 py-2 bg-slate-900/50 rounded-lg border border-white/5">
                                    <div className="text-xs text-slate-500 uppercase tracking-wider">{t.sun}</div>
                                    <div className="font-serif text-xl text-yellow-400">
                                        {tz[initialChartData.planets.find(p => p.name === "Sun")?.sign || ""] || "--"}
                                    </div>
                                </div>
                                <div className="text-center px-4 py-2 bg-slate-900/50 rounded-lg border border-white/5">
                                    <div className="text-xs text-slate-500 uppercase tracking-wider">{t.moon}</div>
                                    <div className="font-serif text-xl text-slate-300">
                                        {tz[initialChartData.planets.find(p => p.name === "Moon" || p.name === "Luna" || p.name === "moon")?.sign || ""] || "--"}
                                    </div>
                                </div>
                                <div className="text-center px-4 py-2 bg-slate-900/50 rounded-lg border border-white/5">
                                    <div className="text-xs text-slate-500 uppercase tracking-wider">{t.asc}</div>
                                    <div className="font-serif text-xl text-indigo-400">
                                        {tz[initialChartData.planets.find(p => p.name === "Ascendant")?.sign || ""] || "--"}
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </AnimatedSection>

            {initialChartData ? (
                <div className="space-y-12">
                    {/* CHART VISUALIZATION */}
                    <AnimatedSection delay={0.1}>
                        <div className="flex flex-col items-center gap-8 py-8">
                            {/* Daily Horoscope moved here */}
                            <div className="w-full max-w-lg mb-8">
                                <DailyHoroscopeCard />
                            </div>

                            <AstrologyWheel planets={initialChartData.planets} houses={initialChartData.houses} size={400} />

                            {!interpretation && (
                                <AuraActionButton
                                    onClick={handleInterpret}
                                    loading={isLoading}
                                    cost={auraCost}
                                    label={t_interp('generate_button')}
                                    icon={<Wand2 className="w-5 h-5" />}
                                />
                            )}
                        </div>
                    </AnimatedSection>

                    {/* AI INTERPRETATION SECTION */}
                    {interpretation && (
                        <AnimatedSection delay={0.1}>
                            <div id="astro-interpretation">
                                <AstroInterpretation data={interpretation} locale={locale} />
                            </div>
                            <div className="flex justify-center mt-8">
                                <Button
                                    variant="outline"
                                    onClick={handleInterpret}
                                    disabled={isLoading}
                                    className="text-xs text-slate-400 border-white/5 hover:border-indigo-500/30 glass"
                                >
                                    {isLoading ? <Loader2 className="w-3 h-3 animate-spin mr-2" /> : <Sparkles className="w-3 h-3 mr-2" />}
                                    {t_interp('regenerate_button')} ({t_interp('aura_cost_badge', { cost: auraCost })})
                                </Button>
                            </div>
                        </AnimatedSection>
                    )}

                    <div className="h-px bg-gradient-to-r from-transparent via-white/10 to-transparent my-12" />

                    {/* PLANETS SECTION */}
                    <AnimatedSection delay={0.2}>
                        {/* The rest of the planets/aspects/houses UI goes here */}
                        <h2 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                            <Disc className="w-5 h-5 text-indigo-500" />
                            {t.planets_title}
                        </h2>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {initialChartData.planets.map((planet, i) => (
                                <GlowingBorderCard key={`${planet.name}-${i}`} glowColor="purple" className="h-full">
                                    <div className="p-4 flex items-center justify-between h-full">
                                        <div className="flex items-center gap-3">
                                            <div className="w-14 h-14 rounded-full bg-slate-900/50 flex items-center justify-center border border-white/10 shadow-lg shadow-indigo-500/5 transition-transform hover:scale-105">
                                                <PlanetIcon name={planet.name} size={36} />
                                            </div>
                                            <div>
                                                <div className="font-bold text-white">
                                                    {t.planets[planet.name] || planet.name}
                                                </div>
                                                <div className="text-xs text-slate-400">
                                                    {t.house_label.replace('{number}', planet.house.toString())}
                                                </div>
                                            </div>
                                        </div>
                                        <div className="text-right">
                                            <div className="font-serif text-lg text-indigo-300">
                                                {tz[planet.sign] || planet.sign}
                                            </div>
                                            <div className="text-xs text-slate-500">
                                                {(planet.normDegree ?? 0).toFixed(2)}°
                                            </div>
                                        </div>
                                    </div>
                                </GlowingBorderCard>
                            ))}
                        </div>
                    </AnimatedSection>

                    {/* ASPECTS SECTION */}
                    <AnimatedSection delay={0.25}>
                        <h2 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                            <Sparkles className="w-5 h-5 text-indigo-500" />
                            {t.aspects_title}
                        </h2>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                            {initialChartData.aspects?.map((aspect, i) => (
                                <div key={i} className="flex items-center justify-between p-4 rounded-xl bg-slate-900/40 border border-white/5 hover:bg-slate-900/60 transition-colors">
                                    <div className="flex items-center gap-3">
                                        <div className="flex items-center gap-1">
                                            <PlanetIcon name={aspect.planet1} size={18} className="text-slate-300" />
                                            <span className="text-sm font-medium text-slate-200">{t.planets[aspect.planet1] || aspect.planet1}</span>
                                        </div>
                                        <span className="text-xs text-slate-500">vs</span>
                                        <div className="flex items-center gap-1">
                                            <PlanetIcon name={aspect.planet2} size={18} className="text-slate-300" />
                                            <span className="text-sm font-medium text-slate-200">{t.planets[aspect.planet2] || aspect.planet2}</span>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <div className="text-xs font-bold text-indigo-300 uppercase tracking-wider">
                                            {t.aspects[aspect.type] || aspect.type}
                                        </div>
                                        <div className="text-[10px] text-slate-500 font-mono">
                                            {aspect.orb.toFixed(2)}° orb
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </AnimatedSection>

                    {/* HOUSES SECTION */}
                    <AnimatedSection delay={0.3}>
                        <h2 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                            <Compass className="w-5 h-5 text-indigo-500" />
                            {t.houses_title}
                        </h2>
                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-4">
                            {initialChartData.houses.map((house) => (
                                <GlowingBorderCard key={house.house} glowColor="indigo" className="h-full group">
                                    <div className="p-3 flex flex-col items-center text-center space-y-2">
                                        <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                                            {t.house_label.replace('{number}', house.house.toString())}
                                        </span>

                                        <div className="relative">
                                            <div className="absolute inset-0 bg-indigo-500/20 blur-xl rounded-full scale-150 opacity-0 group-hover:opacity-100 transition-opacity" />
                                            <ZodiacIcon name={house.sign} size={28} className="relative z-10 transition-transform group-hover:scale-110" />
                                        </div>

                                        <div>
                                            <div className="font-serif text-sm text-white group-hover:text-indigo-300 transition-colors">
                                                {tz[house.sign] || house.sign}
                                            </div>
                                            <div className="text-[9px] text-slate-500 font-mono mt-0.5 opacity-60 group-hover:opacity-100 transition-opacity">
                                                {t.cusp_label.replace('{degree}', house.fullDegree.toFixed(1))}
                                            </div>
                                        </div>
                                    </div>
                                </GlowingBorderCard>
                            ))}
                        </div>
                    </AnimatedSection>
                </div>
            ) : (
                <AnimatedSection delay={0.1}>
                    <div className="glass p-12 text-center rounded-3xl border border-dashed border-slate-700">
                        <Star className="w-16 h-16 text-slate-600 mx-auto mb-6" />
                        <h2 className="text-2xl font-serif text-slate-200 mb-2">{t.no_data_title}</h2>
                        <p className="text-slate-400 mb-6">{t.no_data_description}</p>
                        <Link href="/dashboard/profile">
                            <Button variant="outline">{t.complete_profile_button}</Button>
                        </Link>
                    </div>
                </AnimatedSection>
            )}
            <InsufficientAuraModal
                isOpen={insufficientAuraModalOpen}
                onClose={() => setInsufficientAuraModalOpen(false)}
                requiredAmount={auraCost}
                currentBalance={balance || 0}
            />
        </main>
    );
}

"use client";

import { motion } from "framer-motion";
import { PlanetPosition, HouseCusp } from "@/lib/astrology-api";

import PlanetIcon, { PLANET_COLORS } from "./PlanetIcon";

interface AstrologyWheelProps {
    planets: PlanetPosition[];
    houses: HouseCusp[];
    size?: number;
}

import { useState, useEffect } from "react";
import { useTranslations } from "next-intl";

const ZODIAC_SIGNS = [
    { name: "Aries", symbol: "♈", color: "#ef4444" },
    { name: "Taurus", symbol: "♉", color: "#f59e0b" },
    { name: "Gemini", symbol: "♊", color: "#10b981" },
    { name: "Cancer", symbol: "♋", color: "#3b82f6" },
    { name: "Leo", symbol: "♌", color: "#fbbf24" },
    { name: "Virgo", symbol: "♍", color: "#059669" },
    { name: "Libra", symbol: "♎", color: "#ec4899" },
    { name: "Scorpio", symbol: "♏", color: "#991b1b" },
    { name: "Sagittarius", symbol: "♐", color: "#a855f7" },
    { name: "Capricorn", symbol: "♑", color: "#64748b" },
    { name: "Aquarius", symbol: "♒", color: "#2563eb" },
    { name: "Pisces", symbol: "♓", color: "#6366f1" },
];

export default function AstrologyWheel({ planets, houses, size = 500 }: AstrologyWheelProps) {
    const [mounted, setMounted] = useState(false);
    const t = useTranslations('AstrologyPage');
    const tz = useTranslations('Zodiac');

    useEffect(() => { setMounted(true); }, []);

    const radius = size / 2;
    const center = radius;
    const innerRadius = radius * 0.75;
    const midRadius = radius * 0.88;

    if (!mounted) return <div style={{ width: size, height: size }} />;

    return (
        <div className="relative flex items-center justify-center select-none" style={{ width: size, height: size }}>
            {/* Background Glows */}
            <div className="absolute inset-0 bg-indigo-500/10 rounded-full blur-[100px]" />
            <div className="absolute inset-20 bg-purple-500/5 rounded-full blur-[60px] animate-pulse" />

            <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="relative z-10 drop-shadow-[0_0_20px_rgba(99,102,241,0.3)]">
                <defs>
                    <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                        <feGaussianBlur stdDeviation="1.5" result="blur" />
                        <feComposite in="SourceGraphic" in2="blur" operator="over" />
                    </filter>
                </defs>

                {/* 1. Zodiac Segments */}
                {ZODIAC_SIGNS.map((sign, i) => {
                    const startAngle = i * 30;
                    const endAngle = (i + 1) * 30;

                    const polarToCartesian = (centerX: number, centerY: number, radius: number, angleInDegrees: number) => {
                        const angleInRadians = (angleInDegrees - 90) * Math.PI / 180.0;
                        return {
                            x: Number((centerX + (radius * Math.cos(angleInRadians))).toFixed(3)),
                            y: Number((centerY + (radius * Math.sin(angleInRadians))).toFixed(3))
                        };
                    };

                    const start = polarToCartesian(center, center, radius, startAngle);
                    const end = polarToCartesian(center, center, radius, endAngle);
                    const startInner = polarToCartesian(center, center, innerRadius, startAngle);
                    const endInner = polarToCartesian(center, center, innerRadius, endAngle);

                    const d = `M ${start.x} ${start.y} A ${radius} ${radius} 0 0 1 ${end.x} ${end.y} L ${endInner.x} ${endInner.y} A ${innerRadius} ${innerRadius} 0 0 0 ${startInner.x} ${startInner.y} Z`;

                    return (
                        <g key={sign.name} className="group">
                            <title>{tz(sign.name)}</title>
                            <path
                                d={d}
                                fill="rgba(15, 23, 42, 0.4)"
                                stroke="rgba(99, 102, 241, 0.4)"
                                strokeWidth="1.5"
                                className="transition-all group-hover:fill-indigo-500/10 cursor-pointer"
                            />
                            <text
                                x={polarToCartesian(center, center, midRadius, startAngle + 15).x}
                                y={polarToCartesian(center, center, midRadius, startAngle + 15).y}
                                fill="white"
                                fontSize="26"
                                fontWeight="bold"
                                textAnchor="middle"
                                alignmentBaseline="middle"
                                className="opacity-80 group-hover:opacity-100 group-hover:scale-110 transition-all pointer-events-none drop-shadow-[0_0_8px_rgba(255,255,255,0.6)]"
                            >
                                {sign.symbol}
                            </text>
                        </g>
                    );
                })}

                {/* 2. Concentric Rings */}
                <circle cx={center} cy={center} r={radius} fill="none" stroke="rgba(99, 102, 241, 0.6)" strokeWidth="2.5" />
                <circle cx={center} cy={center} r={innerRadius} fill="none" stroke="rgba(99, 102, 241, 0.7)" strokeWidth="1.5" />
                <circle cx={center} cy={center} r={innerRadius - 40} fill="none" stroke="rgba(255,255,255,0.2)" strokeWidth="1" />

                {/* 3. Planets */}
                {planets.map((planet, idx) => {
                    const angle = planet.fullDegree;
                    const angleInRadians = (angle - 90) * Math.PI / 180.0;
                    const pRadius = innerRadius - 20;
                    const x = Number((center + (pRadius * Math.cos(angleInRadians))).toFixed(3));
                    const y = Number((center + (pRadius * Math.sin(angleInRadians))).toFixed(3));
                    const pColor = PLANET_COLORS[planet.name] || "#ffffff";

                    return (
                        <motion.g
                            key={`${planet.name}-${idx}`}
                            initial={{ scale: 0, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            transition={{ delay: 0.2 + (idx * 0.05), type: "spring" }}
                        >
                            <line
                                x1={center} y1={center} x2={x} y2={y}
                                stroke={pColor}
                                strokeOpacity="0.7"
                                strokeWidth="3"
                                strokeDasharray="6 4"
                            />

                            <g className="cursor-help transition-transform hover:scale-110">
                                {/* Enhanced Glow */}
                                <circle cx={x} cy={y} r="20" fill={pColor} className="opacity-30 blur-[6px]" />
                                <circle cx={x} cy={y} r="16" fill="rgba(15, 23, 42, 0.95)" stroke={pColor} strokeWidth="2.5" />

                                {/* Custom SVG Glyph - Centered and Enlarged */}
                                <g transform={`translate(${x - 14}, ${y - 14})`}>
                                    <PlanetIcon name={planet.name} size={28} />
                                </g>

                                <title>
                                    {t.rich(`planets.${planet.name}`, { fallback: () => planet.name }) as any} {t('in_sign')} {planet.sign !== "---" ? tz.rich(planet.sign, { fallback: () => planet.sign }) as any : "---"} ({planet.normDegree.toFixed(1)}°)
                                </title>
                            </g>
                        </motion.g>
                    );
                })}

                {/* 4. Houses */}
                {houses.map((house) => {
                    const angle = house.fullDegree;
                    const angleInRadians = (angle - 90) * Math.PI / 180.0;
                    const x1 = Number((center + (innerRadius * Math.cos(angleInRadians))).toFixed(3));
                    const y1 = Number((center + (innerRadius * Math.sin(angleInRadians))).toFixed(3));
                    const x2 = Number((center + ((innerRadius - 60) * Math.cos(angleInRadians))).toFixed(3));
                    const y2 = Number((center + ((innerRadius - 60) * Math.sin(angleInRadians))).toFixed(3));

                    return (
                        <line
                            key={`house-${house.house}`}
                            x1={x1} y1={y1} x2={x2} y2={y2}
                            stroke="rgba(255,255,255,0.5)"
                            strokeWidth="2"
                        />
                    );
                })}

                {/* Core */}
                <circle cx={center} cy={center} r="15" fill="white" className="animate-pulse opacity-10" />
                <circle cx={center} cy={center} r="5" fill="white" className="filter drop-shadow-[0_0_10px_white]" />
            </svg>

            {/* Glass Overlay Centered */}
            <div
                className="absolute rounded-full border border-white/20 bg-slate-950/70 backdrop-blur-[6px] shadow-[inset_0_0_20px_rgba(255,255,255,0.05)]"
                style={{
                    width: (innerRadius - 60) * 2,
                    height: (innerRadius - 60) * 2,
                    zIndex: 5
                }}
            />
        </div>
    );
}

"use client";

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Sparkles, Loader2, Star, Sun, Moon, Wand2 } from "lucide-react";
import { toast } from "sonner";
import { useRouter, useParams } from "next/navigation";
import { useTranslations } from "next-intl";
import AuraActionButton from "@/components/ui/AuraActionButton";

interface DailyHoroscopeData {
    headline: string;
    message: string;
    power_action: string;
    lucky_color: string;
    lucky_number: number;
    creditsUsed?: number;
    newBalance?: number;
    alreadyExists?: boolean;
}

export default function DailyHoroscopeCard() {
    const [loading, setLoading] = useState(false);
    const [data, setData] = useState<DailyHoroscopeData | null>(null);
    const router = useRouter();
    const params = useParams();
    const locale = (params?.locale as string) || 'es';
    const t = useTranslations('Dashboard.DailyHoroscope');

    // Check if we already have it in local state/cache or just let the user trigger it?
    // Let's load it automatically if it exists, or show a "Reveal" button.
    // For V1, we show a "Reveal My Daily Guide" button to be explicit about action/cost.

    useEffect(() => {
        const checkExisting = async () => {
            try {
                // Don't set loading true here to avoid flashing spinner if not found
                // Or maybe small loading state?
                const res = await fetch(`/api/astrology/daily?locale=${locale}`);
                if (res.ok) {
                    const data = await res.json();
                    if (data) {
                        setData(data);
                    }
                } else if (res.status === 404) {
                    // No horoscope found, this is normal for first visit/day
                    setData(null);
                }
            } catch (e) {
                // Ignore fetch errors for cleaner console
            }
        };

        checkExisting();
    }, [locale]);

    const handleReveal = async () => {
        setLoading(true);
        try {
            const res = await fetch('/api/astrology/daily', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ locale })
            });

            const result = await res.json();

            if (!res.ok) {
                if (res.status === 402) {
                    toast.error(t('insufficient_aura'), {
                        description: t('insufficient_aura_desc')
                    });
                    // Open credits modal (optional)
                    return;
                }
                throw new Error(result.error || t('error_desc'));
            }

            setData(result);
            if (result.creditsUsed && result.creditsUsed > 0) {
                toast.success(t('revealed'), {
                    description: t('revealed_desc', { cost: result.creditsUsed })
                });
                // TODO: Update global balance context if available
                router.refresh();
            } else if (result.alreadyExists) {
                toast.info(t('recovered'), {
                    description: t('recovered_desc')
                });
            }

        } catch (error: any) {
            toast.error(t('error_title'), {
                description: error.message || t('error_desc')
            });
        } finally {
            setLoading(false);
        }
    };

    if (data) {
        return (
            <Card className="border-purple-500/30 bg-black/40 backdrop-blur-sm text-white overflow-hidden relative">
                <div className="absolute inset-0 bg-gradient-to-br from-purple-900/10 to-blue-900/10 pointer-events-none" />
                <CardHeader className="pb-2">
                    <CardTitle className="text-xl font-serif text-purple-200 flex items-center gap-2">
                        <Sun className="w-5 h-5 text-yellow-500" />
                        {t('title')}
                    </CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="bg-purple-900/20 p-4 rounded-lg border border-purple-500/20">
                        <h3 className="font-bold text-lg text-purple-100 mb-2">{data.headline}</h3>
                        <p className="text-gray-300 text-sm leading-relaxed">{data.message}</p>
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                        <div className="bg-blue-900/20 p-3 rounded-lg border border-blue-500/20">
                            <span className="text-xs text-blue-300 uppercase font-bold tracking-wider">{t('power_action')}</span>
                            <p className="text-sm text-blue-100 mt-1">{data.power_action}</p>
                        </div>
                        <div className="space-y-3">
                            <div className="bg-slate-800/50 p-2 rounded flex items-center justify-between">
                                <span className="text-xs text-gray-400">{t('color')}</span>
                                <span className="text-xs font-bold" style={{ color: data.lucky_color }}>{data.lucky_color}</span>
                            </div>
                            <div className="bg-slate-800/50 p-2 rounded flex items-center justify-between">
                                <span className="text-xs text-gray-400">{t('number')}</span>
                                <span className="text-xs font-bold text-white">{data.lucky_number}</span>
                            </div>
                        </div>
                    </div>
                </CardContent>
            </Card>
        );
    }

    return (
        <Card className="border-dashed border-purple-500/30 bg-black/20 text-white relative overflow-hidden group hover:border-purple-500/60 transition-colors">
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-purple-500/5 to-transparent -translate-x-full group-hover:animate-shimmer" />

            <CardContent className="flex flex-col items-center justify-center py-8 space-y-4">
                <div className="relative">
                    <div className="absolute inset-0 bg-purple-500 blur-xl opacity-20 animate-pulse" />
                    <Sparkles className="w-10 h-10 text-purple-300 relative z-10" />
                </div>

                <div className="text-center space-y-1">
                    <h3 className="text-lg font-medium text-purple-100">{t('subtitle')}</h3>
                    <p className="text-xs text-gray-400 max-w-[250px] mx-auto">
                        {t('description')}
                    </p>
                </div>

                <AuraActionButton
                    onClick={handleReveal}
                    loading={loading}
                    cost={10}
                    label={t('reveal_button')}
                    icon={<Wand2 className="w-4 h-4 text-yellow-400" />}
                    className="min-w-[160px]"
                />
            </CardContent>
        </Card>
    );
}

"use client";

import { Card } from "@/components/ui/card";
import { Sparkles, Layers } from "lucide-react";
import { cn } from "@/lib/utils";
import { useConfig } from "@/components/providers/ConfigProvider";
import { GoldenClassicFrame, MysticSilverFrame, CelestialFrame, GoldenOrnateFrame } from "@/components/features/tarot/frames";
import { useTranslations } from 'next-intl';

interface CardStatsProps {
    stats: {
        card_name: string;
        times_drawn: number;
    } | null;
    className?: string;
}

const ROMAN_NUMERALS = [
    "0", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X",
    "XI", "XII", "XIII", "XIV", "XV", "XVI", "XVII", "XVIII", "XIX", "XX", "XXI"
];

export default function CardStats({ stats, className }: CardStatsProps) {
    const t = useTranslations('Dashboard.tarot');
    const tc = useTranslations('Tarot');
    const { tarotFrame } = useConfig();

    // Convertir el array de nombres de cartas del JSON a una lista
    const DECK_EN = [
        "The Fool", "The Magician", "The High Priestess", "The Empress", "The Emperor",
        "The Hierophant", "The Lovers", "The Chariot", "Strength", "The Hermit",
        "Wheel of Fortune", "Justice", "The Hanged Man", "Death",
        "Temperance", "The Devil", "The Tower", "The Star", "The Moon",
        "The Sun", "Judgement", "The World"
    ];
    const DECK_ES = [
        "El Loco", "El Mago", "La Sacerdotisa", "La Emperatriz", "El Emperador",
        "El Hierofante", "Los Enamorados", "El Carro", "La Fuerza", "El Ermitaño",
        "La Rueda de la Fortuna", "La Justicia", "El Colgado", "La Muerte",
        "La Templanza", "El Diablo", "La Torre", "La Estrella", "La Luna",
        "El Sol", "El Juicio", "El Mundo"
    ];

    // Buscar en ambos idiomas por si acaso
    let cardIndex = stats ? DECK_ES.indexOf(stats.card_name) : -1;
    if (cardIndex === -1 && stats) {
        cardIndex = DECK_EN.indexOf(stats.card_name);
    }

    const imageUrl = cardIndex !== -1 ? `/assets/tarot/arcano-${cardIndex}.jpg` : null;
    const localizedCardName = cardIndex !== -1 ? tc.raw('cards')[cardIndex] : "???";

    const renderFrame = () => {
        const frameClass = "absolute inset-0 z-20 pointer-events-none w-full h-full";
        switch (tarotFrame) {
            case "mystic": return <MysticSilverFrame className={frameClass} />;
            case "classic": return <GoldenClassicFrame className={frameClass} />;
            case "ornate": return <GoldenOrnateFrame className={frameClass} />;
            case "celestial":
            default: return <CelestialFrame className={frameClass} />;
        }
    };

    return (
        <Card className={cn(
            // Restauramos p-4 para alinear títulos con el resto del dashboard
            "bg-gradient-to-br from-indigo-950/40 via-slate-900/60 to-purple-950/40 border-white/5 p-4 flex flex-col gap-0 h-full relative overflow-hidden group",
            className
        )}>

            {/* Header: Título e Icono solamente en el flujo */}
            <div className="flex justify-between items-start relative z-10 w-full shrink-0">
                <div className="flex items-center gap-2 text-indigo-300/90 pt-0">
                    <Sparkles className="w-3.5 h-3.5" />
                    <span className="text-[10px] uppercase tracking-wider font-bold leading-none">{t('stats_title')}</span>
                </div>
            </div>

            {/* Contador de Frecuencia: Absoluto para no afectar al nombre */}
            <div className="absolute top-3 right-3 z-20 text-4xl font-serif font-bold text-indigo-400/40 leading-none drop-shadow-[0_0_12px_rgba(129,140,248,0.2)]">
                {t('stats_count', { count: stats?.times_drawn || 0 })}
            </div>

            {/* Título (Nombre de la carta): En la misma fila que el número */}
            <div className="w-full relative z-10 shrink-0 mt-2 flex items-center justify-center gap-4">
                <div className="w-9 h-9 min-w-[36px] rounded-full border border-indigo-500/30 flex items-center justify-center bg-indigo-500/5 shadow-[0_0_15px_rgba(99,102,241,0.1)]">
                    <span className="text-indigo-300 font-serif font-bold text-xs">
                        {cardIndex !== -1 ? ROMAN_NUMERALS[cardIndex] : "?"}
                    </span>
                </div>
                <div className="text-2xl font-serif font-bold text-white tracking-wide drop-shadow-[0_0_8px_rgba(255,255,255,0.2)]">
                    {localizedCardName}
                </div>
            </div>

            {/* Contenedor de Imagen */}
            <div className="flex-1 flex items-center justify-center relative min-h-0 w-full py-2">
                {imageUrl ? (
                    <div className="relative flex items-center justify-center h-full aspect-[2/3] max-h-[210px]">
                        <div className="absolute inset-0 bg-indigo-500/5 rounded-full blur-2xl group-hover:bg-indigo-500/10 transition-all" />

                        {/* El Marco Global */}
                        {renderFrame()}

                        <div className="relative w-full h-full z-10 p-[4px]">
                            <img
                                src={imageUrl}
                                alt={stats?.card_name}
                                className="w-full h-full object-cover rounded-[10px] shadow-2xl transition-all duration-500 group-hover:scale-[1.02]"
                            />
                        </div>
                    </div>
                ) : (
                    <div className="w-full h-full border-2 border-dashed border-white/5 rounded-xl flex items-center justify-center opacity-30">
                        <Layers className="w-6 h-6 text-slate-400" />
                    </div>
                )}
            </div>

            {/* Decoración: Centrada verticalmente y alineada a la derecha como en las otras tarjetas */}
            <div className="absolute top-1/2 -translate-y-1/2 right-0 p-3 opacity-10 group-hover:opacity-15 pointer-events-none transition-all group-hover:scale-110 group-hover:rotate-12 duration-500">
                <Sparkles className="w-16 h-16 text-indigo-400" />
            </div>
        </Card>
    );
}

"use client";

import { Card } from "@/components/ui/card";
import { Sparkles, Trophy, Coins } from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";
import type { UserBalance } from "@/types";
import { useTranslations } from 'next-intl';

export default function CreditsDisplay({ minimal = false }: { minimal?: boolean }) {
    const t = useTranslations('Dashboard');
    const [balance, setBalance] = useState<number | null>(null);

    // Fetch credits
    useEffect(() => {
        fetch('/api/credits')
            .then(res => res.json())
            .then((data: UserBalance) => {
                if (data && typeof data.balance === 'number') {
                    setBalance(data.balance);
                }
            })
            .catch(err => console.error("Error fetching credits:", err));
    }, []);

    // Escuchar eventos de actualización de créditos (custom event)
    useEffect(() => {
        const handleUpdate = (e: any) => {
            if (e.detail?.newBalance !== undefined) {
                setBalance(e.detail.newBalance);
            }
        };
        window.addEventListener('credits-updated', handleUpdate);
        return () => window.removeEventListener('credits-updated', handleUpdate);
    }, []);

    if (minimal) {
        return (
            <div className="flex items-center gap-2 bg-purple-900/40 border border-purple-500/30 px-3 py-1.5 rounded-full text-sm font-medium text-purple-200">
                <Sparkles className="w-4 h-4 text-yellow-400" />
                <span>{balance !== null ? balance : "..."}</span>
            </div>
        );
    }

    return (
        <Link href="/purchase" className="block group h-full">
            <Card className="h-full bg-gradient-to-br from-indigo-950 to-purple-950 border-purple-500/20 p-4 relative overflow-hidden group-hover:border-purple-500/40 transition-all group-hover:scale-[1.01] cursor-pointer">
                <div className="absolute top-1/2 -translate-y-1/2 right-0 p-3 opacity-10 group-hover:opacity-20 transition-all group-hover:scale-110 duration-500">
                    <Sparkles className="w-16 h-16 text-yellow-500" />
                </div>

                <div className="relative z-10">
                    <div className="flex items-center gap-2 mb-1 text-purple-300">
                        <Sparkles className="w-3.5 h-3.5" />
                        <span className="text-[10px] uppercase tracking-wider font-bold">{t('aura')}</span>
                    </div>

                    <div className="flex items-baseline gap-1.5">
                        <span className="text-3xl font-bold text-white font-serif">
                            {balance !== null ? balance : "---"}
                        </span>
                        <span className="text-xs text-purple-200">Aura</span>
                    </div>

                    {/* Indicador visual de que es clickeable */}
                    <div className="mt-4 flex items-center gap-1.5 text-purple-400 group-hover:text-purple-300 transition-colors">
                        <Coins className="w-3.5 h-3.5" />
                        <span className="text-[10px] uppercase tracking-wider font-bold">{t('aura')} - Recarga</span>
                    </div>
                </div>
            </Card>
        </Link>
    );
}

